--
-- Table structure for table `login_attempts`
--

CREATE TABLE `login_attempts` (
  `ip` varchar(45) NOT NULL,
  `fails` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `last_fail` datetime DEFAULT NULL,
  `locked_until` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `members`
--

CREATE TABLE `members` (
  `id` int(10) UNSIGNED NOT NULL,
  `legacy_id` varchar(100) NOT NULL,
  `member_no` varchar(32) NOT NULL,
  `first_name` varchar(120) DEFAULT NULL,
  `middle_name` varchar(120) DEFAULT NULL,
  `last_name` varchar(120) DEFAULT NULL,
  `suffix` varchar(30) DEFAULT NULL,
  `birthdate` date DEFAULT NULL,
  `gender` varchar(60) DEFAULT NULL,
  `gender_other` varchar(120) DEFAULT NULL,
  `civil_status` varchar(40) DEFAULT NULL,
  `religion` varchar(120) DEFAULT NULL,
  `religion_other` varchar(120) DEFAULT NULL,
  `house_no` varchar(30) DEFAULT NULL,
  `street` varchar(120) DEFAULT NULL,
  `purok` varchar(60) DEFAULT NULL,
  `mobile` varchar(30) DEFAULT NULL,
  `email` varchar(254) DEFAULT NULL,
  `facebook` varchar(120) DEFAULT NULL,
  `classification` varchar(80) DEFAULT NULL,
  `classification_other` varchar(120) DEFAULT NULL,
  `education_level` varchar(120) DEFAULT NULL,
  `education_other` varchar(120) DEFAULT NULL,
  `education_status` varchar(80) DEFAULT NULL,
  `education_status_other` varchar(120) DEFAULT NULL,
  `school` varchar(160) DEFAULT NULL,
  `school_other` varchar(160) DEFAULT NULL,
  `employment` varchar(80) DEFAULT NULL,
  `employment_other` varchar(120) DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `occupation_other` varchar(120) DEFAULT NULL,
  `training` varchar(120) DEFAULT NULL,
  `training_other` varchar(120) DEFAULT NULL,
  `pwd` varchar(3) DEFAULT NULL,
  `disability_type` varchar(80) DEFAULT NULL,
  `disability_other` varchar(120) DEFAULT NULL,
  `sk_voter` varchar(3) DEFAULT NULL,
  `voter_no` varchar(30) DEFAULT NULL,
  `interests` longtext DEFAULT NULL,
  `interest_other` varchar(120) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `photo` varchar(500) NOT NULL DEFAULT '',
  `barangay` varchar(120) DEFAULT NULL,
  `city` varchar(120) DEFAULT NULL,
  `province` varchar(120) DEFAULT NULL,
